      "ipcCode": "",
      "fTerm": "DETAILS, COMPONENTS, OR ACCESSORIES FOR MACHINE TOOLS, e.g. ARRANGEMENTS FOR COPYING OR CONTROLLING (tools of the kind used in lathes or boring machines <b>B23B 27/00</b>); MACHINE TOOLS IN GENERAL, CHARACTERISED BY THE CONSTRUCTION OF PARTICULAR DETAILS OR COMPONENTS; COMBINATIONS OR ASSOCIATIONS OF METAL-WORKING MACHINES, NOT DIRECTED TO A PARTICULAR RESULT<br><br><b><u>Note(s)</u></b><br><br><ul type=\"\"1\"\"><li>In this subclass, groups designating parts of machine tools cover machine tools characterised by constructional features of such parts.<b>[3]</b></li><li>Attention is drawn to the Notes following the title of class <b>B23</b>.</li></ul><br><br><b><u>Subclass indexes</u></b><br><table width=\"100%\"><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">BASIC COMPONENTS OF MACHINE TOOLS</td><td><b>1/00</b>, <b>9/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">DEVICES FOR SUPPORTING, HANDLING, OR FEEDING WORK OR TOOLS</td><td><b>3/00</b>, <b>5/00</b>, <b>7/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">AUXILIARY EQUIPMENT, SAFETY DEVICES</td><td><b>11/00</b>, <b>13/00</b>, <b>27/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">MEASURING; INDICATING; CONTROLLING</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Controlling the movements of the tool or work</td><td><b>15/00</b>, <b>16/00</b>, <b>23/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Indicating</td><td><b>17/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">COPYING</td><td><b>33/00</b>, <b>35/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">MACHINES COMPRISING UNITS OR SUB-ASSEMBLIES, TRANSFER MACHINES, ASSOCIATIONS OF MACHINES OR UNITS</td><td><b>37/00</b>, <b>39/00</b>, <b>41/00</b></td></p></tr></table>",
