      "level": 0,
      "parent": null,
      "ja": "形式の異った機械またはそれらの組合せの部分を構成することができるように設計された少なくともいくつかのユニットを含む複数のユニットからなる金属加工機械，またはそれらの組合せ；互換性の特徴が重要である上記のユニット（特定の金属加工作業に関する特徴，適当なサブクラス，例．Ｂ２３Ｐ２３／００を参照）",
      "en": "Metal-working machines, or constructional combinations thereof, built-up from units designed so that at least some of the units can form parts of different machines or combinations; Units therefor in so far as the feature of interchangeability is important (features relating to particular metal-working operations, <u>see</u> the relevant subclasses, e.g. B23P 23/00)",
