      "code": "B23Q41/00\\",
      "level": 0,
      "parent": null,
      "ja": "クラスＢ２１，Ｂ２３，またはＢ２４による特定の結果を目的としない金属加工機械の組合せ（Ｂ２３Ｑ３７／００，Ｂ２３Ｑ３９／００が優先；行われる作業の特徴は，もし異なる金属加工作業が同一種類ならば，その作業の種類のためのサブクラスを，例．打抜き加工Ｂ２１Ｄ，溶接Ｂ２３Ｋ，研削Ｂ２４Ｂ，を参照；異なる金属加工作業の技術的に特定な組合せの特徴Ｂ２３Ｐ２３／００）",
      "en": "Combinations or associations of metal-working machines not directed to a particular result according to classes B21, B23, or B24 (B23Q 37/00, B23Q 39/00 take precedence; features relating to operations performed, if the different metal-working operations are of the same kind, <u>see</u> the subclass for the kind of operation, e.g. punching B21D, welding B23K, grinding B24B; features relating to technically specified combinations of different metal-working operations B23P 23/00)",
